try:
 import selfies
 s='[C][C][C][Branch1][C][C][C][Branch1][C][C][O]'
 smi=selfies.decoder(s)
 print('Decoded SMILES:',smi)
 try:
  from rdkit import Chem
  m=Chem.MolFromSmiles(smi)
  print('RDKit canonical SMILES:',Chem.MolToSmiles(m) if m else None)
 except Exception as e: print('RDKit validation unavailable:',e)
except Exception as e: print('SELFIES decoding unavailable:',repr(e))
